/**
 * Copies the repo-root DESIGN.md into dist/ so it ships with the published
 * package.
 *
 * The root file is the single source of truth (generated by
 * `pnpm build-tokens`). npm's `files` field cannot reference a path outside the
 * package, so the published copy is produced here as build output rather than
 * committed a second time.
 */
const fs = require('fs');
const path = require('path');

const source = path.resolve(__dirname, '../../../DESIGN.md');
const destination = path.resolve(__dirname, '../dist/DESIGN.md');

if (!fs.existsSync(source)) {
  console.error(
    `Expected ${source} to exist. Run \`pnpm build-tokens\` to generate it before building.`
  );
  process.exit(1);
}

fs.mkdirSync(path.dirname(destination), { recursive: true });
fs.copyFileSync(source, destination);
console.log('Copied DESIGN.md into dist/');
